/**
 * Petrilac chat widget — self-contained embed script.
 *
 * Usage: add this before </body> on petrilac.com:
 *   <script src="https://YOUR_STATIC_HOST/petrilac-chat-widget.js"
 *           data-endpoint="https://petrilac-chatbot.YOUR-SUBDOMAIN.workers.dev/chat"></script>
 *
 * data-endpoint should point at the deployed Cloudflare Worker's /chat route.
 */
(function () {
  var CURRENT_SCRIPT = document.currentScript;
  var ENDPOINT = (CURRENT_SCRIPT && CURRENT_SCRIPT.getAttribute("data-endpoint")) || "";

  if (!ENDPOINT) {
    console.error("[Petrilac chat widget] falta data-endpoint en el <script> tag.");
    return;
  }

  var STORAGE_KEY = "petrilac_chat_history_v1";
  // Paleta real del sitio (tomada de los CTA/botones de petrilac.com):
  var BRAND_COLOR = "#F05423";
  var BRAND_COLOR_DARK = "#D1431A";
  var BRAND_ACCENT = "#FF5100";
  var FONT_STACK = "'Montserrat', -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, Arial, sans-serif";
  var MASCOT_URI = "data:image/png;base64,";

  var state = {
    open: false,
    history: [], // [{role, content}]
    sending: false,
  };

  try {
    var saved = sessionStorage.getItem(STORAGE_KEY);
    if (saved) state.history = JSON.parse(saved);
  } catch (e) {
    /* ignore */
  }

  function persist() {
    try {
      sessionStorage.setItem(STORAGE_KEY, JSON.stringify(state.history.slice(-16)));
    } catch (e) {
      /* ignore */
    }
  }

  // ---- styles ----
  var style = document.createElement("style");
  style.textContent = [
    "#pt-chat-bubble{position:fixed;bottom:18px;right:20px;width:68px;height:68px;border-radius:50%;",
    "background:radial-gradient(circle at 32% 28%," + BRAND_ACCENT + "," + BRAND_COLOR_DARK + " 72%);",
    "box-shadow:0 6px 20px rgba(208,67,26,.4);cursor:pointer;padding:0;",
    "display:flex;align-items:center;justify-content:center;z-index:999999;border:none;",
    "transition:transform .18s ease,box-shadow .18s ease;}",
    "#pt-chat-bubble:hover{transform:scale(1.07);box-shadow:0 8px 26px rgba(208,67,26,.5);}",
    "#pt-chat-bubble:active{transform:scale(.97);}",
    "#pt-chat-bubble img{width:92%;height:92%;object-fit:contain;pointer-events:none;",
    "filter:drop-shadow(0 2px 3px rgba(0,0,0,.18));transition:transform .2s ease;}",
    "#pt-chat-bubble.pt-open img{transform:scale(0.88) rotate(-6deg);}",
    "#pt-chat-close-x{position:absolute;top:-3px;right:-3px;width:22px;height:22px;border-radius:50%;",
    "background:#fff;color:" + BRAND_COLOR_DARK + ";font-size:14px;line-height:1;display:none;",
    "align-items:center;justify-content:center;box-shadow:0 2px 6px rgba(0,0,0,.25);font-weight:700;}",
    "#pt-chat-bubble.pt-open #pt-chat-close-x{display:flex;}",
    "@keyframes pt-pop{0%{opacity:0;transform:translateY(14px) scale(.97);}100%{opacity:1;transform:translateY(0) scale(1);}}",
    "@keyframes pt-fade-in{from{opacity:0;transform:translateY(6px);}to{opacity:1;transform:translateY(0);}}",
    "@keyframes pt-bounce{0%,80%,100%{transform:scale(0);opacity:.4;}40%{transform:scale(1);opacity:1;}}",
    "#pt-chat-panel{position:fixed;bottom:98px;right:20px;width:368px;max-width:92vw;height:540px;max-height:75vh;",
    "background:#fff;border-radius:18px;box-shadow:0 16px 48px rgba(20,20,20,.18),0 2px 8px rgba(20,20,20,.08);",
    "display:none;flex-direction:column;overflow:hidden;z-index:999999;font-family:" + FONT_STACK + ";}",
    "#pt-chat-panel.pt-open{display:flex;animation:pt-pop .22s cubic-bezier(.2,.9,.3,1.3);}",
    "#pt-chat-header{background:linear-gradient(120deg," + BRAND_COLOR + "," + BRAND_ACCENT + ");color:#fff;",
    "padding:14px 18px;display:flex;align-items:center;gap:10px;justify-content:space-between;flex-shrink:0;}",
    "#pt-chat-header-left{display:flex;align-items:center;gap:10px;}",
    "#pt-chat-header-avatar{width:38px;height:38px;border-radius:50%;background:rgba(255,255,255,.22);",
    "display:flex;align-items:center;justify-content:center;flex-shrink:0;}",
    "#pt-chat-header-avatar img{width:82%;height:82%;object-fit:contain;}",
    "#pt-chat-header-title{display:flex;flex-direction:column;line-height:1.25;}",
    "#pt-chat-header-title b{font-size:14.5px;font-weight:700;letter-spacing:.01em;}",
    "#pt-chat-header-title span{font-size:11.5px;opacity:.9;display:flex;align-items:center;gap:5px;}",
    "#pt-chat-header-dot{width:7px;height:7px;border-radius:50%;background:#8CFF8C;",
    "box-shadow:0 0 0 2px rgba(255,255,255,.3);flex-shrink:0;}",
    "#pt-chat-close{background:rgba(255,255,255,.18);border:none;color:#fff;font-size:18px;cursor:pointer;",
    "line-height:1;width:28px;height:28px;border-radius:50%;flex-shrink:0;transition:background .15s ease;}",
    "#pt-chat-close:hover{background:rgba(255,255,255,.32);}",
    "#pt-chat-messages{flex:1;overflow-y:auto;padding:16px 14px;display:flex;flex-direction:column;gap:10px;",
    "background:#faf9f8;}",
    "#pt-chat-messages::-webkit-scrollbar{width:6px;}",
    "#pt-chat-messages::-webkit-scrollbar-thumb{background:#e0ddd9;border-radius:3px;}",
    ".pt-msg{max-width:84%;padding:10px 13px;border-radius:14px;font-size:13.5px;line-height:1.5;",
    "white-space:pre-wrap;word-wrap:break-word;animation:pt-fade-in .25s ease;}",
    ".pt-msg-user{align-self:flex-end;background:" + BRAND_COLOR + ";color:#fff;border-bottom-right-radius:4px;}",
    ".pt-msg-bot{align-self:flex-start;background:#fff;color:#2a2a2a;border:1px solid #ece9e6;",
    "border-bottom-left-radius:4px;box-shadow:0 1px 2px rgba(0,0,0,.03);}",
    ".pt-typing-dots{align-self:flex-start;background:#fff;border:1px solid #ece9e6;border-radius:14px;",
    "border-bottom-left-radius:4px;padding:12px 14px;display:flex;gap:4px;align-items:center;animation:pt-fade-in .2s ease;}",
    ".pt-typing-dots span{width:6px;height:6px;border-radius:50%;background:#c9c5c0;display:inline-block;",
    "animation:pt-bounce 1.3s infinite ease-in-out both;}",
    ".pt-typing-dots span:nth-child(2){animation-delay:.15s;}",
    ".pt-typing-dots span:nth-child(3){animation-delay:.3s;}",
    "#pt-chat-inputrow{display:flex;border-top:1px solid #eee;padding:10px;gap:8px;background:#fff;flex-shrink:0;}",
    "#pt-chat-input{flex:1;border:1.5px solid #e5e2de;border-radius:22px;padding:10px 15px;font-size:13.5px;",
    "outline:none;resize:none;font-family:inherit;max-height:80px;transition:border-color .15s ease;}",
    "#pt-chat-input:focus{border-color:" + BRAND_COLOR + ";}",
    "#pt-chat-send{background:" + BRAND_COLOR + ";border:none;color:#fff;border-radius:50%;width:40px;height:40px;",
    "flex-shrink:0;cursor:pointer;display:flex;align-items:center;justify-content:center;",
    "transition:background .15s ease,transform .1s ease;}",
    "#pt-chat-send:hover:not(:disabled){background:" + BRAND_COLOR_DARK + ";}",
    "#pt-chat-send:active:not(:disabled){transform:scale(.93);}",
    "#pt-chat-send:disabled{background:#e5e2de;cursor:default;}",
    "#pt-chat-send svg{width:16px;height:16px;fill:#fff;margin-left:-1px;}",
    "#pt-chat-footer{text-align:center;font-size:10px;color:#b3aeaa;padding:5px 0 9px;background:#fff;",
    "letter-spacing:.01em;}",
    "@media (max-width:480px){#pt-chat-panel{right:10px;left:10px;width:auto;bottom:92px;}",
    "#pt-chat-bubble{right:14px;bottom:14px;}}",
  ].join("");
  document.head.appendChild(style);

  // ---- DOM ----
  var bubble = document.createElement("button");
  bubble.id = "pt-chat-bubble";
  bubble.setAttribute("aria-label", "Abrir chat de Petrilac");
  bubble.innerHTML =
    '<img src="' + MASCOT_URI + '" alt="" />' +
    '<span id="pt-chat-close-x" aria-hidden="true">&times;</span>';

  var panel = document.createElement("div");
  panel.id = "pt-chat-panel";
  panel.innerHTML =
    '<div id="pt-chat-header">' +
    '<div id="pt-chat-header-left">' +
    '<div id="pt-chat-header-avatar"><img src="' + MASCOT_URI + '" alt="" /></div>' +
    '<div id="pt-chat-header-title"><b>Petrilac</b><span><i id="pt-chat-header-dot" aria-hidden="true"></i>Asesor de productos</span></div>' +
    "</div>" +
    '<button id="pt-chat-close" aria-label="Cerrar">&times;</button>' +
    "</div>" +
    '<div id="pt-chat-messages"></div>' +
    '<div id="pt-chat-inputrow">' +
    '<textarea id="pt-chat-input" rows="1" placeholder="Escribí tu consulta..."></textarea>' +
    '<button id="pt-chat-send" aria-label="Enviar"><svg viewBox="0 0 24 24"><path d="M2 21l21-9L2 3v7l15 2-15 2z"/></svg></button>' +
    "</div>" +
    '<div id="pt-chat-footer">Asistente automático — puede cometer errores</div>';

  document.body.appendChild(bubble);
  document.body.appendChild(panel);

  var messagesEl = panel.querySelector("#pt-chat-messages");
  var inputEl = panel.querySelector("#pt-chat-input");
  var sendBtn = panel.querySelector("#pt-chat-send");
  var closeBtn = panel.querySelector("#pt-chat-close");

  function scrollToBottom() {
    messagesEl.scrollTop = messagesEl.scrollHeight;
  }

  function renderMessage(role, content) {
    var div = document.createElement("div");
    div.className = "pt-msg " + (role === "user" ? "pt-msg-user" : "pt-msg-bot");
    div.textContent = content;
    messagesEl.appendChild(div);
    scrollToBottom();
    return div;
  }

  function renderHistory() {
    messagesEl.innerHTML = "";
    if (state.history.length === 0) {
      renderMessage(
        "assistant",
        "¡Hola! Soy el asesor de productos de Petrilac. Contame en qué superficie estás trabajando (madera, metal, piso, pared, techo, náutica) y si es interior o exterior, y te ayudo a elegir el producto."
      );
      return;
    }
    state.history.forEach(function (m) {
      renderMessage(m.role, m.content);
    });
  }

  function setOpen(open) {
    state.open = open;
    panel.classList.toggle("pt-open", open);
    bubble.classList.toggle("pt-open", open);
    if (open) {
      renderHistory();
      inputEl.focus();
    }
  }

  bubble.addEventListener("click", function () {
    setOpen(!state.open);
  });
  closeBtn.addEventListener("click", function () {
    setOpen(false);
  });

  inputEl.addEventListener("input", function () {
    inputEl.style.height = "auto";
    inputEl.style.height = Math.min(inputEl.scrollHeight, 80) + "px";
  });

  inputEl.addEventListener("keydown", function (e) {
    if (e.key === "Enter" && !e.shiftKey) {
      e.preventDefault();
      sendMessage();
    }
  });
  sendBtn.addEventListener("click", sendMessage);

  function sendMessage() {
    var text = inputEl.value.trim();
    if (!text || state.sending) return;

    inputEl.value = "";
    inputEl.style.height = "auto";
    state.history.push({ role: "user", content: text });
    renderMessage("user", text);
    persist();

    var typingEl = document.createElement("div");
    typingEl.className = "pt-typing-dots";
    typingEl.innerHTML = "<span></span><span></span><span></span>";
    messagesEl.appendChild(typingEl);
    scrollToBottom();

    state.sending = true;
    sendBtn.disabled = true;

    fetch(ENDPOINT, {
      method: "POST",
      headers: { "Content-Type": "application/json" },
      body: JSON.stringify({
        message: text,
        history: state.history.slice(0, -1).slice(-8),
      }),
    })
      .then(function (res) {
        if (!res.ok) throw new Error("bad_status_" + res.status);
        return res.json();
      })
      .then(function (data) {
        typingEl.remove();
        var reply = data.reply || "Perdón, no pude generar una respuesta. Probá de nuevo en un momento.";
        renderMessage("assistant", reply);
        state.history.push({ role: "assistant", content: reply });
        persist();
      })
      .catch(function () {
        typingEl.remove();
        renderMessage(
          "assistant",
          "Hubo un problema de conexión. Probá de nuevo, o comunicate al 0800.77PETRI (73874)."
        );
      })
      .finally(function () {
        state.sending = false;
        sendBtn.disabled = false;
      });
  }
})();
